/** Polls until the check holds or half a second passes, for effects that land after a socket event. */
export const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

/** Terminates the clients, then stops each server once it has seen its sockets close, so no close is logged after teardown. */
export async function terminateAndStop(
  clients: WebSocket[],
  servers: Array<Pick<HalServer, 'wss' | 'stop'>>
): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
